 $('campTabs').innerHTML=['All',...CAMPS].map(c=>`<button data-c="${c}" class="${S.camp===c?'on':''}">${c==='All'?'All Campuses':c}</button>`).join('');
 $('campTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{S.camp=b.dataset.c;render(1)});
 $('deptGrid').innerHTML=DEPTS.map((x,i)=>{const cs=S.courses.filter(c=>c.dept===x&&inCamp(c.campus));
  return `<div class="card rv" ${d(i)}><h3>${esc(x)}</h3>${cs.length?`<ul>${cs.map(c=>`<li><span>${esc(c.name)}${c.level?`<br><small>${esc(c.level)}${ent(c.level)?' · Entry: '+esc(ent(c.level)):''}</small>`:''}</span><span style="text-align:right"><small>${esc(c.duration)}</small><br><span class="bdg">${esc(c.campus||'')}</span></span></li>`).join('')}</ul>`:'<p class="empty">Courses will be listed soon.</p>'}</div>`}).join('');
 $('annGrid').innerHTML=S.news.length?S.news.map((n,i)=>`<div class="card ann rv" ${d(i)}><time>${esc(n.date)}</time><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div>`).join(''):'<p class="empty">No announcements at the moment.</p>';
 $('galGrid').innerHTML=S.gal.length?S.gal.map((g,i)=>`<figure class="rv" ${d(i)}><img loading="lazy" src="/_blob/${esc(g.assetId)}" alt="${esc(g.caption)}"><figcaption>${esc(g.caption)}</figcaption></figure>`).join(''):'<p class="empty">Photos coming soon.</p>';
 const ri=r=>ROLES.findIndex(x=>x.toLowerCase()===(r||'').toLowerCase()),ml=[];
 ROLES.forEach((r,k)=>{const m=S.staff.filter(p=>ri(p.role)===k);ml.push(...(m.length?m:[{ph:1,role:r}]))});ml.push(...S.staff.filter(p=>ri(p.role)<0));
 $('staffGrid').innerHTML=ml.map((p,i)=>`<div class="card pc rv" ${d(i)}>${p.assetId?`<img class="av" src="/_blob/${esc(p.assetId)}" alt="">`:`<div class="av">${esc((p.ph?p.role:p.name||'?').trim()[0])}</div>`}<h3>${p.ph?'Name coming soon':esc(p.name)}</h3><b>${esc(p.role)}</b><small>${esc(p.dept)}</small><small>${esc(p.campus)}</small></div>`).join('');
 $('testiGrid').innerHTML=S.testi.length?S.testi.map((t,i)=>`<div class="card tc rv" ${d(i)}><p>${esc(t.text)}</p><b>${esc(t.name)}</b><br><small style="color:var(--mu)">${esc(t.role)}</small></div>`).join(''):'<p class="empty">Testimonials coming soon.</p>';
 $('contactBox').innerHTML=[['Main Campus','m'],['Kaare Campus','k']].map(([n,p],i)=>{const a=S.ct[p+'a'],ph=S.ct[p+'p'],e=S.ct[p+'e'];return `<div class="card rv" ${d(i)}><h3>${n}</h3>${a||ph||e?`<p>${esc(a)}</p><p>${esc(ph)}</p><p>${esc(e)}</p>`:'<p class="empty">Details will be added by the administrator.</p>'}</div>`}).join('');
 $('feeBox').innerHTML=S.fees.assetId?`<a class="btn sm" style="background:var(--navy)" href="/_blob/${esc(S.fees.assetId)}" target="_blank" rel="noopener">Download Fee Structure</a>`:'<small class="empty">Fee structure coming soon.</small>';
 const K=S.ct;
 const n0=S.news[0];$('tick').style.display=n0?'block':'none';if(n0)$('tick').innerHTML=`<a href="#news"><b>Latest:</b> ${esc(n0.title)} — ${esc(n0.date)}</a>`;
 $('ftc').innerHTML=[['Main Campus','m'],['Kaare Campus','k']].map(([n,p])=>`<p><b>${n}</b><br>${esc(K[p+'a'])}<br>${esc(K[p+'p'])}<br>${esc(K[p+'e'])}</p>`).join('');
 let w=(K.mp||K.kp||'').replace(/\D/g,'');if(w[0]==='0')w='254'+w.slice(1);$('wa').style.display=w?'flex':'none';if(w)$('wa').href='https://wa.me/'+w;
 const sh=SOC.filter(s=>S.soc[s[0]]).map(s=>`<a class="so" href="${esc(S.soc[s[0]])}" target="_blank" rel="noopener" aria-label="${s[1]}" title="${s[1]}"><svg viewBox="0 0 24 24"><path d="${s[2]}"/></svg></a>`).join('');$('tbS').innerHTML=sh;$('ftS').innerHTML=sh;
 $('entryBox').innerHTML=LV.map((v,i)=>`<div class="card rv" ${d(i)} style="text-align:center;border-top:4px solid var(--org)"><h3>${v[0]}</h3><b>${v[1]}</b><p style="margin:8px 0 0">${esc(ent(v[0]))}</p></div>`).join('');
 reveal();if(P.open){if(P.v==='admin'){if(!noAdm)renderAdmin()}else pl()}
