let lastApp=null;
function mkPdf(a){const d=new window.jspdf.jsPDF({unit:'mm',format:'a4'});const lg=document.querySelector('.brand img');try{d.addImage(lg.src,'JPEG',14,10,26,26)}catch(e){}
 d.setFont('helvetica','bold');d.setFontSize(16);d.text('MURAGA TECHNICAL TRAINING INSTITUTE',46,20);d.setFont('helvetica','normal');d.setFontSize(10);d.text('Innovation & Excellence',46,26);d.setFont('helvetica','bold');d.setFontSize(13);d.text('APPLICATION FORM / ADMISSION SLIP',46,34);
 d.setDrawColor(232,130,42);d.setLineWidth(1);d.line(14,40,196,40);let y=52;
 const row=(k,v)=>{d.setFont('helvetica','bold');d.setFontSize(11);d.text(k+':',16,y);d.setFont('helvetica','normal');const x=d.splitTextToSize(String(v||'-'),120);d.text(x,70,y);y+=Math.max(8,x.length*6)};
 row('Reference No.',a.ref);row('Date applied',a.date);row('Full name',a.name);row('Phone',a.phone);row('Email',a.email);row('Education (KCSE)',a.edu);row('Campus',a.campus);row('Department',a.dept);row('Course applied for',a.course);row('Additional info',a.msg);
 y+=6;d.setFont('helvetica','bold');d.text('Documents to carry when reporting (confirm with the admissions office):',16,y);y+=8;d.setFont('helvetica','normal');
 ['This application form, printed','Original and copy of KCSE result slip or certificate','Copy of National ID or Birth Certificate','Passport-size photographs','Evidence of fee payment','Fee structure is available on the school website'].forEach(x=>{d.text('- '+x,20,y);y+=7});
 y+=10;d.text('Applicant signature: ____________________    Date: ______________',16,y);y+=14;d.text('Admissions officer: ______________________    Stamp:',16,y);return d}
async function dlApp(){if(!window.jspdf)return note('PDF tool could not load. Check your internet connection.');const d=mkPdf(lastApp),f='MTTI-Application-'+lastApp.ref+'.pdf';let dn=null;try{dn=await window.claude.use('downloads')}catch(e){}
 if(dn){try{await dn.save({filename:f,data:d.output('blob')})}catch(e){}}else d.save(f)}
$('sendApp').onclick=async()=>{const v=id=>$(id).value.trim(),m=$('appMsg'),a={ref:'APP-'+new Date().getFullYear()+'-'+Math.random().toString(36).slice(2,7).toUpperCase(),name:v('aN'),phone:v('aP'),email:v('aE'),edu:v('aEd'),campus:v('aCa'),dept:v('aD'),course:v('aCo'),msg:v('aM'),ts:Date.now(),date:new Date().toLocaleDateString('en-GB')};
 if(!a.name||!a.phone){m.innerHTML='<b>Please enter your full name and phone number.</b>';return}
 lastApp=a;let saved=false;try{if(!S.db)throw 0;await S.db.collection('apps').add(a);saved=true}catch(e){}
 const to=(a.campus==='Kaare Campus'?S.ct.ke:S.ct.me)||S.ct.me||S.ct.ke||'',body=['Ref: '+a.ref,'Name: '+a.name,'Phone: '+a.phone,'Email: '+a.email,'Education: '+a.edu,'Campus: '+a.campus,'Department: '+a.dept,'Course: '+a.course,'Info: '+a.msg].join('\n');
 m.innerHTML=`<div class="card" style="margin-top:14px"><h3>Application ready</h3><p>Your reference number is <b>${esc(a.ref)}</b>.</p><p>${saved?'Your application has been received by the admissions office.':'Your application form is ready.'}${!saved&&to?` You can also <a href="mailto:${esc(to)}?subject=${encodeURIComponent('Application '+a.ref)}&body=${encodeURIComponent(body)}" target="_blank"><b>send it by email</b></a>.`:''}</p><button class="btn" id="dlApp">Download Application Form (PDF)</button><p><small>Print it and bring it, with your documents, when reporting.</small></p></div>`;$('dlApp').onclick=guard(dlApp)};
