 if(tab==='social')h+=`<div class="frm"><p>Paste the full page link for each account. Leave blank to hide an icon.</p>${SOC.map(s=>`<label>${s[1]}</label><input id="so_${s[0]}" placeholder="https://" value="${esc(S.soc[s[0]])}">`).join('')}<button class="btn" id="saveS">Save Social Links</button></div>`;
 if(tab==='contact'){const c=S.ct;h+=`<div class="frm">${[['Main Campus','m'],['Kaare Campus','k']].map(([n,p])=>`<h3>${n}</h3><input id="${p}a" placeholder="Address" value="${esc(c[p+'a'])}"><input id="${p}p" placeholder="Phone" value="${esc(c[p+'p'])}"><input id="${p}e" placeholder="Email" value="${esc(c[p+'e'])}">`).join('')}<button class="btn" id="saveK">Save Contact Details</button></div>`}
 if(tab==='apps')h+=`<div class="apps">${li('apps',a=>`<div class="card" style="margin:8px 0"><b>${esc(a.name)}</b> · ${esc(a.date)}<br>${esc(a.phone)} ${esc(a.email)}<br>${esc(a.campus)} · ${esc(a.dept)} · ${esc(a.course)}<br>${esc(a.edu)}<br><i>${esc(a.msg)}</i></div>`)}</div>`;
