let si=0,tm;const go=n=>{si=(n+SL.length)%SL.length;document.querySelectorAll('.sd').forEach((e,i)=>e.classList.toggle('on',i===si));document.querySelectorAll('#dots i').forEach((e,i)=>e.classList.toggle('on',i===si))};
const auto=()=>{clearInterval(tm);tm=setInterval(()=>go(si+1),6000)};go(0);auto();
$('pv').onclick=()=>{go(si-1);auto()};$('nx').onclick=()=>{go(si+1);auto()};$('dots').onclick=e=>{if(e.target.dataset.i){go(+e.target.dataset.i);auto()}};
