 S.db=await cl.use('db');S.assets=await cl.use('assets');const u=await cl.use('user');
 S.canWrite=!!(u&&(u.can('data.write')||u.canEdit()));S.canAdmin=!!(u&&(u.isOwner()||u.canEdit()));S.user=u;try{S.uid=await u.id()}catch(e){}
